where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'For $X \sim \text{Binomial}(n = 100, p = 0.3)$, what are the mean and the SD?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Sampling distributions', 'SD of the sample mean', 1, 'A population has $\sigma = 12$. What is the standard deviation of $\bar{x}$ for random samples of size 36?', '["2","12","0.33","6"]'::jsonb, 0, '$\frac{\sigma}{\sqrt n} = \frac{12}{6} = 2$.', '["Right.","This is the population SD; averages vary less.","This divides by $n$, not $\\sqrt n$.","This divides by 2."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'A population has $\sigma = 12$. What is the standard deviation of $\bar{x}$ for random samples of size 36?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Sampling distributions', 'SD of the sample proportion', 2, 'If $p = 0.4$ and $n = 100$, about what is the standard deviation of $\hat{p}$?', '["0.049","0.24","0.0024","0.4"]'::jsonb, 0, '$\sqrt{\frac{p(1 - p)}{n}} = \sqrt{0.0024} \approx 0.049$.', '["Right.","This is $p(1 - p)$ without dividing by $n$.","This is the variance, not the SD.","This is $p$."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'If $p = 0.4$ and $n = 100$, about what is the standard deviation of $\hat{p}$?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Sampling distributions', 'Central Limit Theorem', 2, 'A population is strongly right-skewed. Random samples of size 50 are taken. What is the shape of the sampling distribution of $\bar{x}$?', '["Approximately normal","Strongly right-skewed","Uniform","Strongly left-skewed"]'::jsonb, 0, 'By the Central Limit Theorem, with $n \ge 30$ the sampling distribution of the mean is approximately normal even when the population is skewed.', '["Right.","Individual values are skewed, but means of large samples are approximately normal.","There is no reason for uniform shape.","Nothing makes it skew left."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'A population is strongly right-skewed. Random samples of size 50 are taken. What is the shape of the sampling distribution of $\bar{x}$?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Sampling distributions', 'Bias and variability', 2, 'Increasing the sample size from 100 to 400 (with the same random method) will:', '["Reduce the variability of the statistic but not any bias","Remove bias from a flawed method","Increase variability","Change the center of the sampling distribution"]'::jsonb, 0, 'Larger samples shrink spread by $\sqrt{4} = 2$ times. Bias comes from the method and does not go away with more data.', '["Right.","A biased method stays biased at any sample size.","Variability goes down.","The center stays the same."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'Increasing the sample size from 100 to 400 (with the same random method) will:');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Sampling distributions', '10% condition', 3, 'Why do we check that the sample is less than 10% of the population when sampling without replacement?', '["So the observations are close enough to independent for the SD formula to hold","So the sampling distribution is normal","So the sample is random","So the sample mean equals the population mean"]'::jsonb, 0, 'Without replacement, draws are slightly dependent. If the sample is small relative to the population, the dependence is negligible and $\frac{\sigma}{\sqrt n}$ is accurate.', '["Right.","Normality is the Large Counts or CLT condition.","Randomness is a separate condition.","No condition makes a statistic equal the parameter."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'Why do we check that the sample is less than 10% of the population when sampling without replacement?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Sampling distributions', 'Unbiased estimators', 1, 'What does it mean for a statistic to be an unbiased estimator of a parameter?', '["The mean of its sampling distribution equals the parameter","It always equals the parameter","Its sampling distribution has small spread","It comes from a large sample"]'::jsonb, 0, 'Unbiased means correct on average: centered on the true value.', '["Right.","Individual samples still vary.","Small spread is low variability, a different property.","Sample size affects variability, not bias."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'What does it mean for a statistic to be an unbiased estimator of a parameter?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Confidence intervals', 'Interpreting confidence level', 2, 'What does "95% confidence" mean for a confidence interval?', '["If we took many samples and built an interval from each, about 95% of the intervals would capture the true parameter","There is a 95% probability that this specific interval contains the parameter","95% of the data fall in the interval","95% of sample means fall in the interval"]'::jsonb, 0, 'Confidence describes the long-run success rate of the method, not the probability for one computed interval.', '["Right.","Once computed, an interval either contains the parameter or it does not.","The interval estimates a parameter, not where the data lie.","The interval is centered on one sample statistic, not on the parameter."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'What does "95% confidence" mean for a confidence interval?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Confidence intervals', 'Margin of error', 2, 'A poll of 400 people finds $\hat{p} = 0.5$. What is the margin of error for a 95% confidence interval?', '["About 0.049","About 0.025","About 0.098","About 0.0025"]'::jsonb, 0, '$1.96\sqrt{\frac{0.5 \cdot 0.5}{400}} = 1.96(0.025) = 0.049$.', '["Right.","This is the standard error without $z^*$.","This doubles the margin of error (the full width).","This uses the variance."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'A poll of 400 people finds $\hat{p} = 0.5$. What is the margin of error for a 95% confidence interval?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Confidence intervals', 'Sample size and margin of error', 2, 'To cut a margin of error in half (same confidence level), the sample size must be:', '["Multiplied by 4","Doubled","Halved","Multiplied by $\\sqrt2$"]'::jsonb, 0, 'Margin of error is proportional to $\frac{1}{\sqrt n}$, so halving it needs $\sqrt n$ to double, which means $n$ times 4.', '["Right.","Doubling $n$ cuts the margin only by a factor of $\\sqrt2$.","A smaller sample increases the margin.","This would reduce it by about 16%."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'To cut a margin of error in half (same confidence level), the sample size must be:');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Confidence intervals', 'Confidence level and width', 1, 'If the confidence level is raised from 90% to 99% with the same data, the interval will:', '["Get wider","Get narrower","Stay the same width","Shift to the right"]'::jsonb, 0, 'Higher confidence requires a larger critical value, so the interval widens.', '["Right.","More confidence needs a wider net.","The critical value changes.","The center stays at the sample statistic."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'If the confidence level is raised from 90% to 99% with the same data, the interval will:');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Confidence intervals', 'Reading an interval', 1, 'A 95% confidence interval for a proportion is (0.42, 0.50). What are the point estimate and margin of error?', '["0.46 and 0.04","0.46 and 0.08","0.42 and 0.08","0.50 and 0.04"]'::jsonb, 0, 'The center is $\frac{0.42 + 0.50}{2} = 0.46$, and the margin is half the width, $0.04$.', '["Right.","0.08 is the full width.","The estimate is the center, not the lower end.","The estimate is the center, not the upper end."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'A 95% confidence interval for a proportion is (0.42, 0.50). What are the point estimate and margin of error?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Confidence intervals', 'Using t', 2, 'When building a confidence interval for a population mean, why is $t^*$ used instead of $z^*$?', '["Because $\\sigma$ is unknown and estimated by $s$","Because the sample is large","Because the data are categorical","Because the population is skewed"]'::jsonb, 0, 'Estimating $\sigma$ with $s$ adds uncertainty, which the heavier-tailed $t$ distribution accounts for.', '["Right.","Large samples make $t$ close to $z$, but the reason is still unknown $\\sigma$.","Categorical data call for proportions and $z$.","Skew affects conditions, not the choice of $t$."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'When building a confidence interval for a population mean, why is $t^*$ used instead of $z^*$?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Significance tests and chi-square', 'P-values', 2, 'In a significance test, what is the p-value?', '["The probability of results at least as extreme as those observed, assuming the null hypothesis is true","The probability that the null hypothesis is true","The probability that the alternative hypothesis is true","The significance level chosen before the test"]'::jsonb, 0, 'A p-value is computed assuming $H_0$ and measures how surprising the data would be.', '["Right.","A p-value is not the probability of $H_0$.","Nor the probability of $H_a$.","That is $\\alpha$."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'In a significance test, what is the p-value?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Significance tests and chi-square', 'Errors', 1, 'What is a Type I error?', '["Rejecting $H_0$ when it is actually true","Failing to reject $H_0$ when it is false","Using the wrong test","Rejecting $H_a$ when it is true"]'::jsonb, 0, 'Type I is a false alarm: rejecting a true null. Its probability is $\alpha$.', '["Right.","That is a Type II error.","That is a mistake, but not a Type I error.","Tests do not reject $H_a$."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'What is a Type I error?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Significance tests and chi-square', 'Conclusions', 2, 'With $\alpha = 0.05$, a test gives p = 0.03. Which is the correct conclusion?', '["Reject $H_0$; there is convincing evidence for $H_a$","Accept $H_0$","Fail to reject $H_0$","Prove $H_a$ is true"]'::jsonb, 0, 'Since $0.03 < 0.05$, we reject $H_0$. A test gives evidence, not proof.', '["Right.","We never \"accept\" $H_0$, and here we reject it.","p is below $\\alpha$, so we reject.","Tests cannot prove a hypothesis."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'With $\alpha = 0.05$, a test gives p = 0.03. Which is the correct conclusion?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Significance tests and chi-square', 'Test statistic', 2, 'Test $H_0: p = 0.5$ with $n = 100$ and $\hat{p} = 0.56$. What is the $z$ statistic?', '["1.2","0.06","0.6","2.4"]'::jsonb, 0, '$SE = \sqrt{\frac{0.5 \cdot 0.5}{100}} = 0.05$. $z = \frac{0.56 - 0.5}{0.05} = 1.2$.', '["Right.","This is the difference, not standardized.","This divides by 0.1.","This divides by 0.025."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'Test $H_0: p = 0.5$ with $n = 100$ and $\hat{p} = 0.56$. What is the $z$ statistic?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Significance tests and chi-square', 'Power', 2, 'Which change increases the power of a significance test?', '["Increasing the sample size","Lowering $\\alpha$ from 0.05 to 0.01","Increasing variability in the data","Making the true effect smaller"]'::jsonb, 0, 'A larger $n$ reduces standard error, making a real effect easier to detect.', '["Right.","A smaller $\\alpha$ makes it harder to reject, lowering power.","More variability hides effects.","Smaller effects are harder to detect."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'Which change increases the power of a significance test?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Significance tests and chi-square', 'Chi-square degrees of freedom', 2, 'A chi-square test for independence uses a two-way table with 3 rows and 4 columns. How many degrees of freedom does it have?', '["6","12","11","7"]'::jsonb, 0, '$df = (r - 1)(c - 1) = 2 \cdot 3 = 6$.', '["Right.","This is the number of cells.","This is cells minus 1 (used for goodness of fit).","This adds $(r - 1) + (c - 1) + 2$."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'A chi-square test for independence uses a two-way table with 3 rows and 4 columns. How many degrees of freedom does it have?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-music-theory', 'Cadences, harmonic function, and form', 'Cadences', 1, 'A phrase ends with V moving to I. What cadence is this?', '["Authentic cadence","Plagal cadence","Half cadence","Deceptive cadence"]'::jsonb, 0, 'Dominant to tonic is an authentic cadence (perfect if both chords are in root position with the tonic in the soprano).', '["Right.","Plagal is IV to I.","A half cadence ends on V.","Deceptive is V to vi."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'ap-music-theory' and stem = 'A phrase ends with V moving to I. What cadence is this?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-music-theory', 'Cadences, harmonic function, and form', 'Cadences', 1, 'Which progression is a plagal cadence?', '["IV to I","V to I","ii to V","V to vi"]'::jsonb, 0, 'The plagal ("Amen") cadence is subdominant to tonic.', '["Right.","That is authentic.","Ending on V is a half cadence.","That is deceptive."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'ap-music-theory' and stem = 'Which progression is a plagal cadence?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-music-theory', 'Cadences, harmonic function, and form', 'Cadences', 2, 'A phrase ends on the V chord, approached from ii6. What cadence is this?', '["Half cadence","Authentic cadence","Plagal cadence","Deceptive cadence"]'::jsonb, 0, 'Any phrase that ends on V is a half cadence; it sounds open.', '["Right.","Authentic ends on I.","Plagal ends IV to I.","Deceptive ends on vi after V."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'ap-music-theory' and stem = 'A phrase ends on the V chord, approached from ii6. What cadence is this?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-music-theory', 'Cadences, harmonic function, and form', 'Cadences', 2, 'In a major key, a phrase ends with V moving to vi. What cadence is this?', '["Deceptive cadence","Authentic cadence","Half cadence","Plagal cadence"]'::jsonb, 0, 'V sets up I, but vi replaces it: the "surprise" is a deceptive cadence.', '["Right.","Authentic resolves to I.","Half ends on V itself.","Plagal is IV to I."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'ap-music-theory' and stem = 'In a major key, a phrase ends with V moving to vi. What cadence is this?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-music-theory', 'Cadences, harmonic function, and form', 'Harmonic function', 2, 'In a major key, which chord most often has predominant function?', '["ii","V","I","vii°"]'::jsonb, 0, 'Predominant chords (ii, IV) lead to the dominant.', '["Right.","V is the dominant itself.","I is tonic.","vii° has dominant function."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'ap-music-theory' and stem = 'In a major key, which chord most often has predominant function?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-music-theory', 'Cadences, harmonic function, and form', 'Phrase and period', 3, 'Two phrases begin with the same melody. The first ends with a half cadence and the second with a perfect authentic cadence. What is this structure?', '["A parallel period","A contrasting period","A phrase group","A double period"]'::jsonb, 0, 'A period has a weaker cadence followed by a stronger one. Matching openings make it parallel.', '["Right.","Contrasting periods begin with different material.","A phrase group lacks the weak-strong cadence pairing.","A double period has four phrases."]'::jsonb, false
where not exists (select 1 from public.ap_questions where course_id = 'ap-music-theory' and stem = 'Two phrases begin with the same melody. The first ends with a half cadence and the second with a perfect authentic cadence. What is this structure?');
-- 52 Hardest questions
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Advanced Math', 'Equivalent expressions', 3, '', 'If $x + \frac{1}{x} = 3$, what is the value of $x^3 + \frac{1}{x^3}$?', '["18","27","24","21"]'::jsonb, 0, 'Cube both sides: $(x + \frac1x)^3 = x^3 + \frac{1}{x^3} + 3(x + \frac1x)$. So $27 = x^3 + \frac{1}{x^3} + 3(3)$, which gives $18$.', '["Right: $27 - 3 \\cdot 3 = 18$.","This is just $3^3$. Cubing a sum also produces the cross terms $3(x + \\frac1x)$, which must be subtracted.","This subtracts only 3 instead of $3(x + \\frac1x) = 9$.","This subtracts 6, as if the cross term were $2(x + \\frac1x)$."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'If $x + \frac{1}{x} = 3$, what is the value of $x^3 + \frac{1}{x^3}$?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Algebra', 'Systems of two linear equations in two variables', 3, '', 'In the system $2x + ky = 4$ and $kx + 8y = 8$, $k$ is a constant. For which value of $k$ does the system have infinitely many solutions?', '["$4$","$-4$","$4$ or $-4$","$2$"]'::jsonb, 0, 'For infinitely many solutions the equations must be multiples: $\frac{2}{k} = \frac{k}{8} = \frac{4}{8}$. From $\frac2k = \frac12$, $k = 4$, and then $\frac{k}{8} = \frac12$ also holds.', '["Right: with $k = 4$ the second equation is exactly twice the first.","With $k = -4$ the coefficients are proportional ($\\frac{2}{-4} = \\frac{-4}{8}$) but the constants are not, so there is no solution.","$k^2 = 16$ makes the lines parallel, but only $k = 4$ makes them the same line.","With $k = 2$ the slopes differ, so there is exactly one solution."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'In the system $2x + ky = 4$ and $kx + 8y = 8$, $k$ is a constant. For which value of $k$ does the system have infinitely many solutions?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Advanced Math', 'Nonlinear functions', 3, '', 'The quadratic function $f$ satisfies $f(1) = f(5) = 0$ and $f(3) = -8$. What is $f(7)$?', '["24","12","48","16"]'::jsonb, 0, 'The zeros give $f(x) = a(x - 1)(x - 5)$. Then $f(3) = a(2)(-2) = -4a = -8$, so $a = 2$, and $f(7) = 2(6)(2) = 24$.', '["Right: $a = 2$, so $f(7) = 2 \\cdot 6 \\cdot 2$.","This forgets the leading coefficient $a = 2$.","This doubles $a$ (uses $a = 4$).","This uses $f(7) = 2 \\cdot f(3)$ in absolute value, which has no basis."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'The quadratic function $f$ satisfies $f(1) = f(5) = 0$ and $f(3) = -8$. What is $f(7)$?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Geometry and Trigonometry', 'Circles', 3, '', 'The circle $x^2 + y^2 - 6x + 8y = k$ is tangent to the $x$-axis. What is the value of $k$?', '["$-9$","$9$","$-16$","$16$"]'::jsonb, 0, 'Complete the squares: $(x - 3)^2 + (y + 4)^2 = k + 25$. The center is $(3, -4)$, 4 units from the $x$-axis, so the radius is 4: $k + 25 = 16$, $k = -9$.', '["Right: $r^2 = 16 = k + 25$.","Sign error: $k = 25 - 16$ instead of $16 - 25$.","This sets $k = -r^2$, forgetting the 25 from completing the square.","This sets $k = r^2$, forgetting that completing the square added 25 to the right side."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'The circle $x^2 + y^2 - 6x + 8y = k$ is tangent to the $x$-axis. What is the value of $k$?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Problem-Solving and Data Analysis', 'Percentages', 3, '', 'A price is increased by 25%. By what percent must the new price be decreased so the final price is 10% less than the original price?', '["28%","35%","15%","22%"]'::jsonb, 0, '$1.25(1 - d) = 0.90$, so $1 - d = 0.72$ and $d = 0.28$, a 28% decrease.', '["Right: $0.90 \\div 1.25 = 0.72$.","This adds the percents ($25 + 10$), but percents of different bases do not add.","This subtracts the percents ($25 - 10$).","This is $0.28 - 0.06$ or a guess; check $1.25 \\times 0.78 = 0.975$, not 0.90."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'A price is increased by 25%. By what percent must the new price be decreased so the final price is 10% less than the original price?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Algebra', 'Linear equations in one variable', 3, '', 'What is the sum of all solutions to $|2x - 5| = x + 1$?', '["$\\frac{22}{3}$","$6$","$\\frac43$","$\\frac{26}{3}$"]'::jsonb, 0, 'Case 1: $2x - 5 = x + 1$ gives $x = 6$ (check: $7 = 7$). Case 2: $2x - 5 = -(x + 1)$ gives $x = \frac43$ (check: $\frac73 = \frac73$). Sum: $6 + \frac43 = \frac{22}{3}$.', '["Right: both solutions check, and they add to $\\frac{22}{3}$.","This is only the first case; the negative case also gives a valid solution.","This is only the second case.","This adds 6 and $\\frac83$; in case 2 the equation is $3x = 4$, not $3x = 8$."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'What is the sum of all solutions to $|2x - 5| = x + 1$?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Geometry and Trigonometry', 'Right triangles and trigonometry', 3, '', 'For an angle measure $x$ with $0 < x < 90$, $\sin(x^\circ) = \cos((2x - 30)^\circ)$. What is $x$?', '["40","20","30","60"]'::jsonb, 0, '$\sin\theta = \cos(90^\circ - \theta)$, so the two angles are complementary: $x + 2x - 30 = 90$, $x = 40$. Then $2x - 30 = 50$, and $40 + 50 = 90$.', '["Right: $3x = 120$.","This solves $x + 2x - 30 = 30$, misusing the identity.","This sets $x = 2x - 30$, as if sine and cosine of the same angle were equal.","This solves $3x - 30 = 150$, treating the angles as supplementary."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'For an angle measure $x$ with $0 < x < 90$, $\sin(x^\circ) = \cos((2x - 30)^\circ)$. What is $x$?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Advanced Math', 'Nonlinear functions', 3, '', 'The function $f(t) = a \cdot b^t$, where $a$ and $b$ are positive constants, satisfies $f(2) = 18$ and $f(5) = 486$. What is $a + b$?', '["5","9","6","11"]'::jsonb, 0, '$\frac{f(5)}{f(2)} = b^3 = 27$, so $b = 3$. Then $a \cdot 9 = 18$, so $a = 2$, and $a + b = 5$.', '["Right: $a = 2$, $b = 3$.","This uses $b = 3$ with $a = 6$ (from $18 \\div 3$, using $b^1$ instead of $b^2$).","This uses $a = 3$, $b = 3$.","This takes $b^3 = 27$ as $b = 9$ then guesses $a$."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'The function $f(t) = a \cdot b^t$, where $a$ and $b$ are positive constants, satisfies $f(2) = 18$ and $f(5) = 486$. What is $a + b$?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Problem-Solving and Data Analysis', 'One-variable data: distributions and measures of center and spread', 3, '', 'The mean of 10 numbers is 20. Two of the numbers, whose mean is 35, are removed. What is the mean of the remaining numbers?', '["16.25","15","17.5","18"]'::jsonb, 0, 'The total is $10 \times 20 = 200$. The two removed numbers total $70$. The remaining 8 numbers total $130$, and $130 \div 8 = 16.25$.', '["Right: $130 \\div 8$.","This removes 35 twice from the mean ($20 - 5$) without accounting for the totals correctly.","This divides 130 by a wrong count or subtracts only one number.","This removes only 35 from the total: $165 \\div 9 \\approx 18.3$."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'The mean of 10 numbers is 20. Two of the numbers, whose mean is 35, are removed. What is the mean of the remaining numbers?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'math', 'Advanced Math', 'Nonlinear equations in one variable', 3, '', 'Which of the following describes the solution set of $\sqrt{x + 7} = x - 5$?', '["$9$ only","$2$ only","$2$ and $9$","No solution"]'::jsonb, 0, 'Squaring: $x + 7 = x^2 - 10x + 25$, so $x^2 - 11x + 18 = 0$ and $x = 2$ or $9$. Check: $x = 9$ gives $4 = 4$. $x = 2$ gives $3 = -3$, false, so 2 is extraneous.', '["Right: only 9 survives the check.","At $x = 2$ the right side is negative, but a square root is never negative.","Squaring can add an extraneous solution; both must be checked.","$x = 9$ works: $\\sqrt{16} = 4 = 9 - 5$."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'Which of the following describes the solution set of $\sqrt{x + 7} = x - 5$?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'rw', 'Craft and Structure', 'Words in Context', 3, '', 'Which choice completes the text with the most logical and precise word or phrase?

The committee''s report was anything but perfunctory: its authors had ______ every claim, tracing each figure back to its original source.', '["scrutinized","dismissed","embellished","summarized"]'::jsonb, 0, '"Anything but perfunctory" means very thorough, and the colon introduces evidence: tracing every figure to its source is careful examination, which is what "scrutinized" means.', '["Right: scrutinize means examine closely, matching the tracing of sources.","Dismissing claims is the opposite of checking each one.","Embellishing adds decoration; it does not fit tracing figures to their sources.","Summarizing could be done quickly, which is what \"perfunctory\" describes; it does not explain the thoroughness."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'Which choice completes the text with the most logical and precise word or phrase?

The committee''s report was anything but perfunctory: its authors had ______ every claim, tracing each figure back to its original source.');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'rw', 'Standard English Conventions', 'Boundaries', 3, '', 'Which choice completes the text so that it conforms to the conventions of Standard English?

The expedition''s findings were ______ the core samples, which spanned 40,000 years, recorded three abrupt warming events.', '["striking: the","striking, the","striking the","striking, and, the"]'::jsonb, 0, 'Two independent clauses meet here, and the second explains the first. A colon can join them.', '["Right: a colon joins two independent clauses when the second explains the first.","A comma alone between two independent clauses is a comma splice.","With no punctuation it is a run-on sentence.","The comma after \"and\" is wrong: a coordinating conjunction is not followed by a comma here."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'Which choice completes the text so that it conforms to the conventions of Standard English?

The expedition''s findings were ______ the core samples, which spanned 40,000 years, recorded three abrupt warming events.');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'rw', 'Standard English Conventions', 'Form, Structure, and Sense', 3, '', 'Which choice completes the text so that it conforms to the conventions of Standard English?

The collection of letters, which archivists only recently discovered in a sealed trunk alongside several of the poet''s diaries, ______ new light on her final years.', '["sheds","shed","have shed","are shedding"]'::jsonb, 0, 'The subject is the singular "collection"; "letters" and "diaries" sit inside modifying phrases. The verb must be singular: "sheds."', '["Right: singular \"collection\" takes \"sheds.\"","\"Shed\" is plural (present tense) and agrees with \"letters,\" which is not the subject.","\"Have\" is plural; the subject is singular.","\"Are\" is plural; the subject is singular."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'Which choice completes the text so that it conforms to the conventions of Standard English?

The collection of letters, which archivists only recently discovered in a sealed trunk alongside several of the poet''s diaries, ______ new light on her final years.');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'rw', 'Expression of Ideas', 'Transitions', 3, '', 'Which choice completes the text with the most logical transition?

Engineers had predicted that the new footbridge would sway dangerously in strong crosswinds. ______ during the 2019 storm, the strongest on record, sensors recorded movement well within safe limits.', '["However,","Similarly,","Therefore,","For example,"]'::jsonb, 0, 'The second sentence contradicts the prediction in the first, so a contrasting transition is needed.', '["Right: the result contrasts with the prediction.","\"Similarly\" signals agreement, but the outcome contradicts the prediction.","\"Therefore\" signals a result, but safe movement does not follow from a prediction of danger.","The storm data is not an example of dangerous swaying; it contradicts it."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'Which choice completes the text with the most logical transition?

Engineers had predicted that the new footbridge would sway dangerously in strong crosswinds. ______ during the 2019 storm, the strongest on record, sensors recorded movement well within safe limits.');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'rw', 'Information and Ideas', 'Inferences', 3, '', 'Which choice most logically completes the text?

In a field study, bumblebees exposed to a low dose of a common pesticide visited 30% fewer flowers per foraging trip than unexposed bees did. Yet when researchers tracked both groups in a flight tunnel, they found no difference in flight speed, endurance, or wingbeat frequency. These results suggest that the pesticide most likely ______', '["affects how bees choose or handle flowers rather than their physical ability to fly.","reduces the number of flowers available near the hive.","makes bees fly more slowly between flowers.","has no effect on bee behavior."]'::jsonb, 0, 'Foraging dropped, but every measure of flying ability was unchanged. So the drop is best explained by something other than flight: decisions or flower handling.', '["Right: flight was normal, so the change is in foraging behavior, not motor ability.","The study measured bee behavior, not flower supply, and both groups were in the same field.","Flight speed showed no difference.","Exposed bees visited 30% fewer flowers, which is an effect."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'Which choice most logically completes the text?

In a field study, bumblebees exposed to a low dose of a common pesticide visited 30% fewer flowers per foraging trip than unexposed bees did. Yet when researchers tracked both groups in a flight tunnel, they found no difference in flight speed, endurance, or wingbeat frequency. These results suggest that the pesticide most likely ______');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'rw', 'Information and Ideas', 'Command of Evidence', 3, '', 'A biologist claims that urban red foxes are bolder toward unfamiliar objects than rural red foxes are. Which finding, if true, would most directly support this claim?', '["When a novel object was placed beside food, urban foxes approached the food sooner, on average, than rural foxes did.","Urban foxes ate a wider variety of foods than rural foxes did.","Rural foxes had larger home ranges than urban foxes had.","Urban and rural foxes approached familiar food dishes equally quickly."]'::jsonb, 0, 'The claim is specifically about boldness toward unfamiliar objects. Only the first finding tests that behavior and shows the urban group bolder.', '["Right: it directly measures reaction to an unfamiliar object and favors urban foxes.","Diet variety is related, but it does not measure response to unfamiliar objects.","Home range size says nothing about boldness toward objects.","Familiar dishes are not unfamiliar objects, and equal speeds would show no difference."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'A biologist claims that urban red foxes are bolder toward unfamiliar objects than rural red foxes are. Which finding, if true, would most directly support this claim?');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'rw', 'Standard English Conventions', 'Form, Structure, and Sense', 3, '', 'Which choice completes the text so that it conforms to the conventions of Standard English?

Each of the three orchestras that toured Europe last spring has released ______ own recording of the program.', '["its","their","they''re","it''s"]'::jsonb, 0, '"Each" is singular, so the pronoun must be singular: "its."', '["Right: singular possessive for singular \"each.\"","\"Their\" is plural; it agrees with \"orchestras,\" which is not the subject.","\"They''re\" means \"they are.\"","\"It''s\" means \"it is.\""]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'Which choice completes the text so that it conforms to the conventions of Standard English?

Each of the three orchestras that toured Europe last spring has released ______ own recording of the program.');
insert into public.questions (test, section, domain, skill, difficulty, passage, stem, choices, answer, expl, choice_expl, challenge)
select 'SAT', 'rw', 'Expression of Ideas', 'Rhetorical Synthesis', 3, '', 'While researching a topic, a student took these notes:
- A 2015 study tracked 400 adults who used a standing desk.
- It found no change in daily calorie burn.
- A 2021 study tracked 1,200 adults who walked on a treadmill desk.
- It found an average of 300 extra calories burned per day.

The student wants to emphasize a difference between the two studies'' findings. Which choice most effectively uses the notes to do this?', '["While standing desk users burned no extra calories, treadmill desk users burned about 300 more per day.","Two studies, one in 2015 and one in 2021, examined desks.","The 2021 study tracked 1,200 adults, three times as many as the 2015 study.","Both studies tracked adults who used alternatives to sitting desks."]'::jsonb, 0, 'The goal is a difference in findings. Only the first choice contrasts the results.', '["Right: it contrasts the two results directly.","This names the studies but states no findings.","This is a difference in sample size, not in findings.","This is a similarity, not a difference."]'::jsonb, true
where not exists (select 1 from public.questions where stem = 'While researching a topic, a student took these notes:
- A 2015 study tracked 400 adults who used a standing desk.
- It found no change in daily calorie burn.
- A 2021 study tracked 1,200 adults who walked on a treadmill desk.
- It found an average of 300 extra calories burned per day.

The student wants to emphasize a difference between the two studies'' findings. Which choice most effectively uses the notes to do this?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'calculus', 'Integrals and the Fundamental Theorem', 'FTC with variable limits', 3, 'If $F(x) = \int_x^{x^2} \sqrt{1 + t^3}\,dt$, what is $F''(x)$?', '["$2x\\sqrt{1 + x^6} - \\sqrt{1 + x^3}$","$\\sqrt{1 + x^6} - \\sqrt{1 + x^3}$","$2x\\sqrt{1 + x^6} + \\sqrt{1 + x^3}$","$2x\\sqrt{1 + x^5} - \\sqrt{1 + x^3}$"]'::jsonb, 0, 'By the Fundamental Theorem with the chain rule: (integrand at upper limit) times (derivative of upper limit) minus (integrand at lower limit) times (derivative of lower limit): $\sqrt{1 + (x^2)^3} \cdot 2x - \sqrt{1 + x^3} \cdot 1$.', '["Right: chain rule on the upper limit, minus the lower limit term.","This forgets the chain-rule factor $2x$ from the upper limit.","The lower limit term is subtracted, not added.","$(x^2)^3 = x^6$, not $x^5$."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'calculus' and stem = 'If $F(x) = \int_x^{x^2} \sqrt{1 + t^3}\,dt$, what is $F''(x)$?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-calc-bc', 'Infinite series and convergence tests (BC)', 'Interval of convergence', 3, 'What is the interval of convergence of $\sum_{n=1}^{\infty} \frac{(x - 2)^n}{n \cdot 3^n}$?', '["$[-1, 5)$","$(-1, 5)$","$(-1, 5]$","$[-1, 5]$"]'::jsonb, 0, 'The ratio test gives $\frac{|x - 2|}{3} < 1$, so $-1 < x < 5$. At $x = 5$ the series is $\sum \frac1n$, the harmonic series, which diverges. At $x = -1$ it is $\sum \frac{(-1)^n}{n}$, which converges by the alternating series test.', '["Right: include $-1$, exclude 5.","The left endpoint gives the alternating harmonic series, which converges.","This flips the endpoints: $x = 5$ gives the divergent harmonic series.","The harmonic series at $x = 5$ diverges."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-calc-bc' and stem = 'What is the interval of convergence of $\sum_{n=1}^{\infty} \frac{(x - 2)^n}{n \cdot 3^n}$?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'statistics', 'Probability rules', 'Conditional probability (Bayes)', 3, 'A disease affects 1% of a population. A test detects it in 90% of people who have it, and gives a false positive for 9% of people who do not. A randomly chosen person tests positive. Approximately what is the probability that this person has the disease?', '["0.09","0.90","0.91","0.01"]'::jsonb, 0, '$P(\text{pos}) = 0.01(0.90) + 0.99(0.09) = 0.009 + 0.0891 = 0.0981$. $P(\text{disease} \mid \text{pos}) = \frac{0.009}{0.0981} \approx 0.092$.', '["Right: true positives are a small share of all positives because the disease is rare.","This is $P(\\text{pos} \\mid \\text{disease})$, the reverse conditional.","This is $1 - 0.09$, the chance a healthy person tests negative.","This ignores the test result and uses the base rate."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'statistics' and stem = 'A disease affects 1% of a population. A test detects it in 90% of people who have it, and gives a false positive for 9% of people who do not. A randomly chosen person tests positive. Approximately what is the probability that this person has the disease?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-precalc', 'Unit 2B: Logarithms', 'Logarithmic equations', 3, 'What is the solution set of $\log_2 x + \log_2 (x - 2) = 3$?', '["$\\{4\\}$","$\\{-2, 4\\}$","$\\{-2\\}$","$\\{5\\}$"]'::jsonb, 0, '$\log_2[x(x - 2)] = 3$ gives $x^2 - 2x = 8$, so $x = 4$ or $x = -2$. The log of a negative number is undefined, so $x = -2$ is rejected.', '["Right: only 4 is in the domain.","$-2$ makes $\\log_2 x$ undefined.","$-2$ is extraneous.","This solves $x + x - 2 = 8$, adding the arguments instead of multiplying."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-precalc' and stem = 'What is the solution set of $\log_2 x + \log_2 (x - 2) = 3$?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-bio', 'Unit 7: Natural Selection', 'Hardy-Weinberg', 3, 'In a population in Hardy-Weinberg equilibrium, 16% of individuals show a recessive phenotype. What fraction of the population is heterozygous?', '["0.48","0.24","0.36","0.16"]'::jsonb, 0, '$q^2 = 0.16$, so $q = 0.4$ and $p = 0.6$. Heterozygotes: $2pq = 2(0.6)(0.4) = 0.48$.', '["Right: $2pq = 0.48$.","This is $pq$, missing the factor of 2.","This is $p^2$, the homozygous dominant fraction.","This is $q^2$, the recessive phenotype itself."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-bio' and stem = 'In a population in Hardy-Weinberg equilibrium, 16% of individuals show a recessive phenotype. What fraction of the population is heterozygous?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-bio', 'Unit 3: Cellular Energetics', 'Enzyme inhibition', 3, 'A molecule binds an enzyme at a site away from the active site and lowers the maximum reaction rate. Adding much more substrate does not restore the original maximum rate. Which best describes the molecule?', '["A noncompetitive (allosteric) inhibitor","A competitive inhibitor","A cofactor","A substrate analog"]'::jsonb, 0, 'Binding away from the active site and lowering Vmax in a way that more substrate cannot overcome is the signature of noncompetitive inhibition.', '["Right: allosteric binding lowers Vmax; more substrate cannot outcompete it.","Competitive inhibitors bind the active site, and enough substrate overcomes them.","Cofactors help enzymes work; they do not lower the maximum rate.","Substrate analogs compete for the active site."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-bio' and stem = 'A molecule binds an enzyme at a site away from the active site and lowers the maximum reaction rate. Adding much more substrate does not restore the original maximum rate. Which best describes the molecule?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-chem', 'Unit 8: Acids and Bases', 'Buffers (Henderson-Hasselbalch)', 3, 'A buffer contains 0.10 M of a weak acid HA ($K_a = 1.0 \times 10^{-5}$) and 0.20 M of its conjugate base. What is the pH? ($\log 2 \approx 0.30$)', '["5.30","4.70","5.00","2.30"]'::jsonb, 0, '$\text{pH} = pK_a + \log\frac{[A^-]}{[HA]} = 5.00 + \log 2 = 5.30$.', '["Right: more base than acid puts pH above $pK_a$.","This uses $\\log\\frac{[HA]}{[A^-]}$, flipping the ratio.","This is $pK_a$, which applies only when the concentrations are equal.","This ignores the buffer and treats it as a plain weak acid with a wrong calculation."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-chem' and stem = 'A buffer contains 0.10 M of a weak acid HA ($K_a = 1.0 \times 10^{-5}$) and 0.20 M of its conjugate base. What is the pH? ($\log 2 \approx 0.30$)');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-chem', 'Unit 9: Thermodynamics and Electrochemistry', 'Gibbs free energy', 3, 'For a reaction, $\Delta H = +40$ kJ/mol and $\Delta S = +100$ J/(mol·K). Assuming both stay constant, under what condition is the reaction thermodynamically favorable?', '["Above 400 K","Below 400 K","Above 0.4 K","At all temperatures"]'::jsonb, 0, '$\Delta G = \Delta H - T\Delta S < 0$ when $T > \frac{\Delta H}{\Delta S} = \frac{40{,}000}{100} = 400$ K.', '["Right: with both positive, high temperature makes $T\\Delta S$ win.","Below 400 K, $\\Delta H$ dominates and $\\Delta G$ is positive.","This forgets to convert kJ to J.","With $\\Delta H > 0$ it is unfavorable at low temperature."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-chem' and stem = 'For a reaction, $\Delta H = +40$ kJ/mol and $\Delta S = +100$ J/(mol·K). Assuming both stay constant, under what condition is the reaction thermodynamically favorable?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-enviro', 'Unit 3: Populations', 'Rule of 70', 3, 'A town of 50,000 grows at a steady 3.5% per year. About how many people will it have after 40 years?', '["200,000","100,000","120,000","400,000"]'::jsonb, 0, 'Doubling time $\approx 70 \div 3.5 = 20$ years. Forty years is two doublings: $50{,}000 \to 100{,}000 \to 200{,}000$.', '["Right: two doublings.","This is only one doubling (20 years).","This adds $3.5\\% \\times 40 = 140\\%$ as simple growth, ignoring compounding.","This is three doublings (60 years)."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-enviro' and stem = 'A town of 50,000 grows at a steady 3.5% per year. About how many people will it have after 40 years?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-physics-1', 'Unit 2: Force and Translational Dynamics', 'Atwood machine', 3, 'Blocks of 3 kg and 1 kg hang on either side of a light, frictionless pulley and are released from rest. Using $g = 10$ m/s², what is the tension in the string?', '["15 N","20 N","30 N","10 N"]'::jsonb, 0, '$a = \frac{(3 - 1)g}{3 + 1} = 5$ m/s². For the 1 kg block moving up: $T - 10 = 1(5)$, so $T = 15$ N. Check with the 3 kg block: $30 - T = 3(5)$, $T = 15$ N.', '["Right: tension lies between the two weights.","This is the weight difference times 10, or the system net force doubled.","This is the weight of the 3 kg block, true only if it were not accelerating.","This is the weight of the 1 kg block, true only if it were not accelerating."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-physics-1' and stem = 'Blocks of 3 kg and 1 kg hang on either side of a light, frictionless pulley and are released from rest. Using $g = 10$ m/s², what is the tension in the string?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-physics-1', 'Unit 6: Energy and Momentum of Rotating Systems', 'Rolling without slipping', 3, 'A solid sphere ($I = \frac25 mr^2$) rolls without slipping from rest down a ramp, dropping a height $h$. What is its speed at the bottom?', '["$\\sqrt{\\frac{10gh}{7}}$","$\\sqrt{2gh}$","$\\sqrt{\\frac{4gh}{3}}$","$\\sqrt{gh}$"]'::jsonb, 0, '$mgh = \frac12 mv^2 + \frac12 \cdot \frac25 mr^2 \cdot \frac{v^2}{r^2} = \frac{7}{10}mv^2$, so $v = \sqrt{\frac{10gh}{7}}$.', '["Right: 2/7 of the energy goes to rotation.","This ignores rotational kinetic energy (a sliding block).","This is for a solid cylinder ($I = \\frac12 mr^2$).","This is for a hoop ($I = mr^2$)."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-physics-1' and stem = 'A solid sphere ($I = \frac25 mr^2$) rolls without slipping from rest down a ramp, dropping a height $h$. What is its speed at the bottom?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-physics-2', 'Electric circuits', 'Series-parallel circuits', 3, 'A 6 Ω and a 3 Ω resistor are in parallel, and that pair is in series with a 4 Ω resistor across an ideal 12 V battery. What is the current through the 3 Ω resistor?', '["$\\frac43$ A","$\\frac23$ A","2 A","4 A"]'::jsonb, 0, 'The parallel pair is $\frac{6 \cdot 3}{6 + 3} = 2$ Ω, total 6 Ω, so the battery current is 2 A. The pair has $2 \times 2 = 4$ V across it, so the 3 Ω resistor carries $\frac43$ A.', '["Right: 4 V across 3 Ω.","This is the current through the 6 Ω resistor.","This is the total current, which splits between the branches.","This puts all 12 V across the 3 Ω resistor."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-physics-2' and stem = 'A 6 Ω and a 3 Ω resistor are in parallel, and that pair is in series with a 4 Ω resistor across an ideal 12 V battery. What is the current through the 3 Ω resistor?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-physics-c-mech', 'Rotation: torque and rotational inertia', 'Angular acceleration of a pivoted rod', 3, 'A uniform rod of length $L$ pivots freely about one end. It is held horizontal and released. What is its angular acceleration just after release?', '["$\\frac{3g}{2L}$","$\\frac{g}{L}$","$\\frac{g}{2L}$","$\\frac{3g}{L}$"]'::jsonb, 0, '$\tau = mg\frac{L}{2}$ and $I = \frac13 mL^2$, so $\alpha = \frac{\tau}{I} = \frac{3g}{2L}$.', '["Right: torque from the center of mass over $\\frac13 mL^2$.","This treats the rod as a point mass at its end.","This uses $I = mL^2$ with torque at the center.","This uses torque $mgL$, as if the weight acted at the far end."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-physics-c-mech' and stem = 'A uniform rod of length $L$ pivots freely about one end. It is held horizontal and released. What is its angular acceleration just after release?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-physics-c-em', 'Electric charges, fields, and Gauss''s law', 'Field inside a charged sphere', 3, 'An insulating solid sphere of radius $R$ carries total charge $Q$ spread uniformly through its volume. What is the field magnitude at a distance $r < R$ from the center?', '["$\\frac{kQr}{R^3}$","$\\frac{kQ}{r^2}$","0","$\\frac{kQ}{R^2}$"]'::jsonb, 0, 'A Gaussian sphere of radius $r$ encloses $Q\frac{r^3}{R^3}$. Gauss''s law gives $E = \frac{kQ_{enc}}{r^2} = \frac{kQr}{R^3}$.', '["Right: the field grows linearly inside.","This uses all of $Q$; only the charge inside radius $r$ counts.","Zero field inside holds for conductors, not a uniformly charged insulator.","This is the field at the surface only."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-physics-c-em' and stem = 'An insulating solid sphere of radius $R$ carries total charge $Q$ spread uniformly through its volume. What is the field magnitude at a distance $r < R$ from the center?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-csa', '2D arrays and recursion', 'Tracing recursion', 3, 'Consider the method:

public static int mystery(int n) {
  if (n <= 1) return 1;
  return n + mystery(n / 2);
}

What does mystery(10) return?', '["18","17","19","15"]'::jsonb, 0, 'Integer division: mystery(10) = 10 + mystery(5); mystery(5) = 5 + mystery(2); mystery(2) = 2 + mystery(1) = 3. So mystery(5) = 8 and mystery(10) = 18.', '["Right: 10 + 5 + 2 + 1.","This leaves off the base case value of 1.","This treats 5 / 2 as 2.5 or adds an extra 1.","This stops at mystery(5) and returns 10 + 5."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-csa' and stem = 'Consider the method:

public static int mystery(int n) {
  if (n <= 1) return 1;
  return n + mystery(n / 2);
}

What does mystery(10) return?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-csp', 'Big Idea 3: Algorithms and Programming', 'Reasonable vs unreasonable time', 3, 'For a list of $n$ items, which algorithm does NOT run in reasonable time?', '["Checking every possible subset of the items","Comparing every pair of items","Sorting the items with a comparison sort","Searching the list once from start to end"]'::jsonb, 0, 'There are $2^n$ subsets, which grows exponentially. The other choices are polynomial ($n^2$, $n \log n$ or $n^2$, and $n$), which counts as reasonable time.', '["Right: $2^n$ is exponential.","Every pair is about $n^2$, which is polynomial and reasonable.","Sorting is at most $n^2$, polynomial.","A single pass is linear."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-csp' and stem = 'For a list of $n$ items, which algorithm does NOT run in reasonable time?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-micro', 'Unit 4: Imperfect Competition', 'Monopoly deadweight loss', 3, 'A monopolist faces demand $P = 100 - Q$ and constant marginal cost of \$20 (no fixed cost). What is the deadweight loss of the monopoly compared with the competitive outcome?', '["\\$800","\\$1,600","\\$400","\\$1,200"]'::jsonb, 0, '$MR = 100 - 2Q = 20$ gives $Q = 40$, $P = 60$. Competitive output is where $P = MC$: $Q = 80$. DWL $= \frac12(60 - 20)(80 - 40) = 800$.', '["Right: triangle with base 40 and height 40.","This forgets the one-half in the triangle area.","This halves the base or the height twice.","This uses the wrong price gap ($80 - 20$)."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-micro' and stem = 'A monopolist faces demand $P = 100 - Q$ and constant marginal cost of \$20 (no fixed cost). What is the deadweight loss of the monopoly compared with the competitive outcome?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-macro', 'Unit 4: The Financial Sector', 'Money multiplier', 3, 'The reserve requirement is 10%, and banks hold no excess reserves. A person deposits \$1,000 of cash from under a mattress into a checking account. What is the maximum change in the money supply?', '["\\$9,000","\\$10,000","\\$900","\\$1,000"]'::jsonb, 0, 'The deposit itself just moves \$1,000 from currency to checking, so it adds nothing. The bank can lend \$900, and the multiplier is $\frac{1}{0.10} = 10$, so new money is $900 \times 10 = 9{,}000$.', '["Right: only the loans create new money.","This counts the deposit as new money, but cash was already in the money supply.","This is only the first loan.","This is the deposit itself, which changes the form of money, not the amount."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-macro' and stem = 'The reserve requirement is 10%, and banks hold no excess reserves. A person deposits \$1,000 of cash from under a mattress into a checking account. What is the maximum change in the money supply?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-macro', 'Unit 3: National Income and Price Determination', 'Balanced budget multiplier', 3, 'The MPC is 0.8. The government raises spending by \$100 billion and raises taxes by \$100 billion. With no other changes, by how much does real GDP change at most?', '["Increases by \\$100 billion","Does not change","Increases by \\$500 billion","Decreases by \\$400 billion"]'::jsonb, 0, 'Spending multiplier: $\frac{1}{0.2} = 5$, so $+500$. Tax multiplier: $-\frac{0.8}{0.2} = -4$, so $-400$. Net: $+100$ billion (the balanced-budget multiplier is 1).', '["Right: $500 - 400 = 100$.","Taxes have a smaller multiplier than spending, so they do not cancel.","This ignores the tax increase.","This counts only the tax increase."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-macro' and stem = 'The MPC is 0.8. The government raises spending by \$100 billion and raises taxes by \$100 billion. With no other changes, by how much does real GDP change at most?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-gov', 'Unit 3: Civil Liberties and Civil Rights', 'Required Supreme Court cases', 3, 'Which pairing of a Supreme Court case and its holding is correct?', '["McDonald v. Chicago: the Second Amendment applies to the states","Gideon v. Wainwright: illegally obtained evidence is excluded","Tinker v. Des Moines: school-sponsored prayer is unconstitutional","Baker v. Carr: school segregation is unconstitutional"]'::jsonb, 0, 'McDonald (2010) incorporated the Second Amendment through the Fourteenth Amendment. The others mix up cases: exclusion is Mapp v. Ohio, school prayer is Engel v. Vitale, and desegregation is Brown v. Board.', '["Right: McDonald incorporated the right to bear arms.","Gideon guaranteed counsel for poor defendants; exclusion is Mapp v. Ohio.","Tinker protected student symbolic speech; school prayer is Engel v. Vitale.","Baker v. Carr opened redistricting to the courts; segregation is Brown v. Board."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-gov' and stem = 'Which pairing of a Supreme Court case and its holding is correct?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'apush', 'Period 5: 1844 to 1877', 'Road to the Civil War', 3, 'Which of these events happened last?', '["The Dred Scott decision","The Kansas-Nebraska Act","The Compromise of 1850","The Wilmot Proviso"]'::jsonb, 0, 'Wilmot Proviso (1846), Compromise of 1850, Kansas-Nebraska Act (1854), Dred Scott v. Sandford (1857).', '["Right: 1857.","1854, three years before Dred Scott.","1850.","1846, the earliest."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'apush' and stem = 'Which of these events happened last?');
