select 'ap-world', 'Unit 6: Consequences of Industrialization (1750 to 1900)', 'Responses to Western expansion', 3, 'Which of these events happened last?', '["The Meiji Restoration","The Taiping Rebellion begins","The Indian Rebellion (Sepoy Mutiny)","The First Opium War begins"]'::jsonb, 0, 'First Opium War (1839), Taiping Rebellion begins (1850), Indian Rebellion (1857), Meiji Restoration (1868).', '["Right: 1868.","1850.","1857.","1839, the earliest."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-world' and stem = 'Which of these events happened last?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-euro', 'Unit 3: Absolutism and Constitutionalism', 'Religious settlements', 3, 'Which settlement first gave Calvinism legal recognition within the Holy Roman Empire?', '["The Peace of Westphalia","The Peace of Augsburg","The Edict of Nantes","The Treaty of Utrecht"]'::jsonb, 0, 'The Peace of Augsburg (1555) let rulers choose only Lutheranism or Catholicism. The Peace of Westphalia (1648) added Calvinism.', '["Right: 1648 added Calvinism.","Augsburg recognized only Lutheranism and Catholicism.","The Edict of Nantes protected Huguenots in France, not in the Holy Roman Empire.","Utrecht (1713) ended the War of the Spanish Succession."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-euro' and stem = 'Which settlement first gave Calvinism legal recognition within the Holy Roman Empire?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-afam', 'Unit 3: The Practice of Freedom', 'Strategies for advancement', 3, 'Which thinker argued in the 1895 Atlanta address that Black Southerners should focus on vocational training and economic progress before pressing for political and social equality?', '["Booker T. Washington","W. E. B. Du Bois","Ida B. Wells","Marcus Garvey"]'::jsonb, 0, 'Booker T. Washington''s Atlanta Compromise speech stressed vocational education and economic self-help. Du Bois criticized it in The Souls of Black Folk (1903).', '["Right: the Atlanta Compromise speech.","Du Bois was the leading critic of that approach and demanded full civil rights.","Wells led anti-lynching journalism.","Garvey''s Pan-Africanist movement came later and centered on Black nationalism."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-afam' and stem = 'Which thinker argued in the 1895 Atlanta address that Black Southerners should focus on vocational training and economic progress before pressing for political and social equality?');
