select 'ap-comp-gov', 'Unit 2: Political Institutions', 'Executive systems', 3, 'Which of the six AP Comparative Government countries has a semi-presidential system, with a directly elected president and a prime minister who must keep the confidence of the legislature?', '["Russia","Mexico","United Kingdom","Nigeria"]'::jsonb, 0, 'Russia has a dual executive: a powerful elected president and a prime minister approved by the Duma.', '["Right: Russia is semi-presidential.","Mexico is presidential, with no prime minister.","The UK is parliamentary; its head of state is a monarch, not an elected president.","Nigeria is presidential, with no prime minister."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-comp-gov' and stem = 'Which of the six AP Comparative Government countries has a semi-presidential system, with a directly elected president and a prime minister who must keep the confidence of the legislature?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-psych', 'Unit 3: Development and Learning', 'Reinforcement schedules', 3, 'Which schedule of reinforcement produces behavior that is most resistant to extinction?', '["Variable-ratio","Fixed-ratio","Fixed-interval","Continuous"]'::jsonb, 0, 'With a variable-ratio schedule, the learner cannot tell when the next reward is coming, so a long run without rewards looks normal and responding continues.', '["Right: unpredictable rewards make extinction hard to notice.","Fixed-ratio produces high rates, but a missing reward is noticed sooner.","Fixed-interval gives a scalloped pattern and extinguishes faster.","Continuous reinforcement extinguishes fastest."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-psych' and stem = 'Which schedule of reinforcement produces behavior that is most resistant to extinction?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-hug', 'Unit 5: Agriculture and Rural Land Use', 'Von Thünen model', 3, 'In the von Thünen model, which activity is located in the ring closest to the market city?', '["Market gardening and dairying","Livestock ranching","Grain farming","Timber harvesting"]'::jsonb, 0, 'Perishable, high-value goods with high transport costs, like vegetables and milk, go nearest the market. (Timber was in the second ring in von Thünen''s original because it was heavy.)', '["Right: perishable goods go nearest the market.","Ranching needs lots of land and goes in the outermost ring.","Grain is durable and goes in the third ring.","Wood was in the second ring, not the first."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-hug' and stem = 'In the von Thünen model, which activity is located in the ring closest to the market city?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-lang', 'The rhetorical situation', 'Concession and rebuttal', 3, '"Granted, the four-day school week will cost the district more in after-school care. Yet the savings on buses and heating will more than cover that cost within two years." What is the main rhetorical function of the first sentence?', '["It concedes an opposing point so the writer can answer it","It states the writer''s thesis","It provides the main evidence for the claim","It undermines the writer''s own position"]'::jsonb, 0, '"Granted" acknowledges a counterargument, and "Yet" begins the rebuttal. Together they make a concession and refutation.', '["Right: concession, then rebuttal.","The thesis is the claim that savings cover the cost; the first sentence is a counterpoint.","The evidence is the savings in the second sentence.","It acknowledges a cost only to answer it, which strengthens the position."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-lang' and stem = '"Granted, the four-day school week will cost the district more in after-school care. Yet the savings on buses and heating will more than cover that cost within two years." What is the main rhetorical function of the first sentence?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-lit', 'Reading and analyzing poetry', 'Meter', 3, 'A line scans as: da-DUM da-DUM da-DUM da-DUM da-DUM da. How is it best described?', '["Iambic pentameter with a feminine ending","Trochaic hexameter","Iambic hexameter","Anapestic pentameter"]'::jsonb, 0, 'There are five iambs (da-DUM) plus one extra unstressed syllable at the end. An extra unstressed final syllable is a feminine ending.', '["Right: five iambs plus an unstressed ending.","Trochees are DUM-da; this line starts unstressed.","There are only five stressed syllables, so it is not hexameter.","Anapests are da-da-DUM."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-lit' and stem = 'A line scans as: da-DUM da-DUM da-DUM da-DUM da-DUM da. How is it best described?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-art-history', 'Early Europe and Colonial Americas', 'Romanesque vs Gothic', 3, 'A church has pointed arches, ribbed groin vaults, flying buttresses, and large stained-glass windows. Which style is it?', '["Gothic","Romanesque","Byzantine","Renaissance"]'::jsonb, 0, 'Pointed arches and flying buttresses carry the weight outward, which lets walls open up for large windows. This is the Gothic system.', '["Right: the full Gothic structural system.","Romanesque uses round arches, barrel vaults, and thick walls with small windows.","Byzantine churches center on domes over pendentives with mosaics.","Renaissance architecture returns to classical round arches and columns."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-art-history' and stem = 'A church has pointed arches, ribbed groin vaults, flying buttresses, and large stained-glass windows. Which style is it?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-music-theory', 'Chords and Roman numerals', 'Augmented sixth chords', 3, 'In C major, which pitches form an Italian augmented sixth chord?', '["A♭, C, F♯","A♭, C, D, F♯","A♭, C, E♭, F♯","A, C, F♯"]'::jsonb, 0, 'The Italian sixth has scale degree ♭6 in the bass, tonic, and ♯4: A♭–C–F♯. The augmented sixth (A♭ up to F♯) resolves outward to G.', '["Right: ♭6, 1, ♯4.","Adding D (scale degree 2) makes it a French sixth.","Adding E♭ makes it a German sixth.","With A natural the interval A–F♯ is a major sixth, not augmented."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-music-theory' and stem = 'In C major, which pitches form an Italian augmented sixth chord?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-seminar', 'Building a research question and method', 'Confounding variables', 3, 'A student finds that schools with later start times have higher test scores and concludes that later start times raise scores. Which is the strongest objection?', '["Schools that start later may differ in other ways, such as funding, that also affect scores","The sample of schools may be too large","Test scores are numerical data","Start times can be measured precisely"]'::jsonb, 0, 'An observational correlation cannot show causation because a confounding variable could explain both.', '["Right: a confounder could cause both.","A larger sample is a strength, not an objection.","Being numerical is not a flaw.","Precise measurement is a strength."]'::jsonb, true
where not exists (select 1 from public.ap_questions where course_id = 'ap-seminar' and stem = 'A student finds that schools with later start times have higher test scores and concludes that later start times raise scores. Which is the strongest objection?');
insert into public.ap_questions (course_id, unit, concept, difficulty, stem, choices, answer, expl, choice_expl, challenge)
select 'ap-art-design', 'How the portfolio is scored', 'Portfolio sections', 3, 'In an AP Art and Design portfolio, how many works are submitted for the Selected Works section, and how many images for the Sustained Investigation?', '["5 works; 15 images","15 works; 5 images","12 works; 12 images","5 works; 10 images"]'::jsonb, 0, 'Selected Works has 5 works with written evidence. Sustained Investigation has 15 digital images showing an inquiry through practice, experimentation, and revision.', '["Right: 5 and 15.","This reverses the two sections.","Neither section uses 12.","The Sustained Investigation requires 15 images, not 10."]'::jsonb, true
